def is_palindrome(s: str) -> bool:
    c = ''.join(ch.lower() for ch in s if ch.isalnum())
    return c == c[::-1]

def second_largest(numbers: list[int]) -> int | None:
    u = sorted(list(set(numbers)))
    return u[-2] if len(u) >= 2 else None

def count_vowels(text: str) -> int:
    v = set('aeiouAEIOU')
    return sum(1 for ch in text if ch in v)

def fizzbuzz(n: int) -> list[str]:
    res = []
    for i in range(1, n + 1):
        if i % 15 == 0: res.append('FizzBuzz')
        elif i % 3 == 0: res.append('Fizz')
        elif i % 5 == 0: res.append('Buzz')
        else: res.append(str(i))
    return res

def word_frequency(text: str) -> dict[str, int]:
    d = {}
    for w in text.lower().split():
        d[w] = d.get(w, 0) + 1
    return d

