def flatten_list(nested: list) -> list:
    out = []
    for x in nested:
        if isinstance(x, list): out.extend(flatten_list(x))
        else: out.append(x)
    return out

def remove_duplicates(items: list) -> list:
    seen = set(); out = []
    for x in items:
        if x not in seen: seen.add(x); out.append(x)
    return out

def longest_common_prefix(strs: list[str]) -> str:
    if not strs: return ''
    p = strs[0]
    for s in strs[1:]:
        while not s.startswith(p):
            p = p[:-1]
            if not p: return ''
    return p

def first_unique_char(s: str) -> int:
    from collections import Counter
    c = Counter(s)
    for i, ch in enumerate(s):
        if c[ch] == 1: return i
    return -1

def is_valid_parentheses(s: str) -> bool:
    m = {')': '(', ']': '[', '}': '{'}
    st = []
    for c in s:
        if c in m.values(): st.append(c)
        elif c in m:
            if not st or st.pop() != m[c]: return False
    return len(st) == 0

def caesar_cipher(text: str, shift: int) -> str:
    res = []
    for c in text:
        if c.isalpha():
            base = ord('A') if c.isupper() else ord('a')
            res.append(chr((ord(c) - base + shift) % 26 + base))
        else: res.append(c)
    return ''.join(res)

def count_consonants(text: str) -> int:
    v = set('aeiouAEIOU')
    return sum(1 for c in text if c.isalpha() and c not in v)

def rotate_list(nums: list, k: int) -> list:
    if not nums: return []
    k = k % len(nums)
    return nums[-k:] + nums[:-k] if k > 0 else list(nums)

def find_missing_number(nums: list[int]) -> int:
    n = len(nums)
    return n * (n + 1) // 2 - sum(nums)

def find_duplicates(nums: list[int]) -> list[int]:
