    return sorted([k for k, v in Counter(nums).items() if v > 1])

def max_subarray_sum(nums: list[int]) -> int:
    cur = m = nums[0]
    for x in nums[1:]:
        cur = max(x, cur + x)
        m = max(m, cur)
    return m

def two_sum(nums: list[int], target: int) -> list[int]:
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen: return [seen[target - x], i]
        seen[x] = i
    return []

def list_difference(a: list, b: list) -> list:
    sb = set(b); seen = set(); out = []
    for x in a:
        if x not in sb and x not in seen:
            seen.add(x); out.append(x)
    return out

def chunk_list(lst: list, size: int) -> list[list]:
    if size <= 0: return []
    return [lst[i:i + size] for i in range(0, len(lst), size)]

def factorial(n: int) -> int:
    if n < 0: raise ValueError()
    res = 1
    for i in range(2, n + 1): res *= i
    return res

def compute_gcd(a: int, b: int) -> int:
    import math
    return math.gcd(a, b)

def compute_lcm(a: int, b: int) -> int:
    import math
    return abs(a * b) // math.gcd(a, b) if a and b else 0

def primes_up_to(n: int) -> list[int]:
    if n < 2: return []
    s = [True] * (n + 1); s[0] = s[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if s[i]: s[i*i:n+1:i] = [False] * len(range(i*i, n+1, i))
    return [i for i, is_p in enumerate(s) if is_p]

def harmonic_sum(n: int) -> float:
    if n <= 0: return 0.0
    return round(sum(1.0 / i for i in range(1, n + 1)), 4)

def compute_variance(numbers: list[float]) -> float:
    if not numbers: return 0.0
    mean = sum(numbers) / len(numbers)
    return round(sum((x - mean) ** 2 for x in numbers) / len(numbers), 3)

def transpose_matrix(matrix: list[list]) -> list[list]:
    if not matrix or not matrix[0]: return []
    return [list(row) for row in zip(*matrix)]

def invert_dict(d: dict) -> dict:
    res = {}
    for k, v in d.items(): res.setdefault(v, []).append(k)
    return res

