def top_k_elements(nums: list[int], k: int) -> list[int]:
    from collections import Counter
    return [item for item, _ in Counter(nums).most_common(k)]

def multiply_matrices(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
    if not a or not b or not a[0] or not b[0]: return []
    m, k, n = len(a), len(b), len(b[0])
    res = [[0] * n for _ in range(m)]
    for i in range(m):
        for j in range(n):
            res[i][j] = sum(a[i][x] * b[x][j] for x in range(k))
    return res

def bubble_sort(arr: list[int]) -> list[int]:
    a = list(arr)
    n = len(a)
    for i in range(n):
        for j in range(0, n - i - 1):
            if a[j] > a[j + 1]: a[j], a[j + 1] = a[j + 1], a[j]
    return a

def insertion_sort(arr: list[int]) -> list[int]:
    a = list(arr)
    for i in range(1, len(a)):
        key = a[i]; j = i - 1
        while j >= 0 and a[j] > key:
            a[j + 1] = a[j]; j -= 1
        a[j + 1] = key
    return a

def selection_sort(arr: list[int]) -> list[int]:
    a = list(arr)
    for i in range(len(a)):
        m = i
        for j in range(i + 1, len(a)):
            if a[j] < a[m]: m = j
        a[i], a[m] = a[m], a[i]
    return a

def quick_sort(arr: list[int]) -> list[int]:
    if len(arr) <= 1: return list(arr)
    p = arr[len(arr) // 2]
    l = [x for x in arr if x < p]
    m = [x for x in arr if x == p]
    r = [x for x in arr if x > p]
    return quick_sort(l) + m + quick_sort(r)

def merge_sort_list(arr: list[int]) -> list[int]:
    if len(arr) <= 1: return list(arr)
    m = len(arr) // 2
    l, r = merge_sort_list(arr[:m]), merge_sort_list(arr[m:])
    res = []; i = j = 0
    while i < len(l) and j < len(r):
        if l[i] <= r[j]: res.append(l[i]); i += 1
        else: res.append(r[j]); j += 1
    res.extend(l[i:]); res.extend(r[j:])
    return res

def compute_mode(nums: list[int]) -> list[int]:
    from collections import Counter
    if not nums: return []
    c = Counter(nums); m = max(c.values())
    return sorted([k for k, v in c.items() if v == m])

def moving_average(nums: list[float], window: int) -> list[float]:
    if window <= 0 or len(nums) < window: return []
    return [round(sum(nums[i:i + window]) / window, 2) for i in range(len(nums) - window + 1)]

def interleave_lists(a: list, b: list) -> list:
    res = []
    for x, y in zip(a, b): res.extend([x, y])
    res.extend(a[len(b):]); res.extend(b[len(a):])
    return res

def cumulative_sums(nums: list[int]) -> list[int]:
    res = []; s = 0
    for x in nums: s += x; res.append(s)
    return res

def min_max_normalize(nums: list[float]) -> list[float]:
    if not nums: return []
    mi, ma = min(nums), max(nums)
    if mi == ma: return [0.0] * len(nums)
    return [round((x - mi) / (ma - mi), 2) for x in nums]

def token_entropy(tokens: list[str]) -> float:
    import math
    from collections import Counter
    if not tokens: return 0.0
    n = len(tokens); c = Counter(tokens)
    return round(-sum((cnt / n) * math.log2(cnt / n) for cnt in c.values()), 3)

def weighted_harmonic_mean(vals: list[float], weights: list[float]) -> float:
    if not vals or len(vals) != len(weights) or sum(weights) == 0: return 0.0
    return round(sum(weights) / sum(w / v for v, w in zip(vals, weights)), 3)

def parse_kv_pairs(text: str) -> dict[str, str]:
    res = {}
    for part in text.split(';'):
        part = part.strip()
        if '=' in part:
            k, v = part.split('=', 1)
            res[k.strip()] = v.strip()
    return res

