def count_interval_overlaps(intervals: list[tuple[int, int]]) -> int:
    count = 0; n = len(intervals)
    for i in range(n):
        for j in range(i + 1, n):
            if max(intervals[i][0], intervals[j][0]) <= min(intervals[i][1], intervals[j][1]): count += 1
    return count

def count_subsequence_matches(text: str, sub: str) -> int:
    m, n = len(text), len(sub)
    dp = [0] * (n + 1); dp[0] = 1
    for c in text:
        for j in range(n - 1, -1, -1):
            if c == sub[j]: dp[j + 1] += dp[j]
    return dp[n]

def sparse_vector_dot(v1: dict[int, float], v2: dict[int, float]) -> float:
    common = set(v1.keys()) & set(v2.keys())
    return round(sum(v1[k] * v2[k] for k in common), 3)

def balanced_ternary_str(n: int) -> str:
    if n == 0: return '0'
    digits = []
    while n != 0:
        rem = (n % 3 + 3) % 3
        if rem == 0: digits.append('0'); n //= 3
        elif rem == 1: digits.append('+'); n = (n - 1) // 3
        else: digits.append('-'); n = (n + 1) // 3
    return ''.join(reversed(digits))

def longest_consecutive_streak(items: list[int]) -> int:
    s = set(items); m = 0
    for x in s:
        if x - 1 not in s:
            cur = x; streak = 1
            while cur + 1 in s: cur += 1; streak += 1
            m = max(m, streak)
    return m

def boustrophedon_order(matrix: list[list[int]]) -> list[int]:
    out = []
    for i, row in enumerate(matrix):
        out.extend(row if i % 2 == 0 else row[::-1])
    return out

def prefix_suffix_common(s: str) -> int:
    n = len(s)
    for l in range(n - 1, 0, -1):
        if s[:l] == s[n - l:]: return l
    return 0

def group_by_mod(nums: list[int], m: int) -> dict[int, list[int]]:
    if m <= 0: return {}
    res = {}
    for x in nums: res.setdefault(x % m, []).append(x)
    return res

